using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using StarviaBackend.Modules.Ai.Core.Chats.Entities;

namespace StarviaBackend.Modules.Ai.Infrastructure.EF.Chats.Configurations.Write;

internal sealed class ChatConfiguration : IEntityTypeConfiguration<Chat>
{
    public void Configure(EntityTypeBuilder<Chat> builder)
    {
        builder.ToTable("Chats");
        builder.HasKey(x => x.Id);

        // Ids are generated by the domain. Telling EF the store never generates them makes it treat a
        // message added to an already tracked chat as new (Added) instead of an existing one (Modified).
        builder.Property(x => x.Id).ValueGeneratedNever();

        builder.Property(x => x.UserId).IsRequired();
        builder.Property(x => x.Type).IsRequired();
        builder.Property(x => x.Title).IsRequired().HasMaxLength(Chat.MaxTitleLength);
        builder.Property(x => x.Status).IsRequired();
        builder.Property(x => x.PostId);
        builder.Property(x => x.LastMessageAt);
        builder.Property(x => x.CreatedAt).IsRequired();

        // The chat history is always listed per user, most recently active first.
        builder.HasIndex(x => new { x.UserId, x.LastMessageAt });

        builder.HasMany(x => x.Messages)
            .WithOne(x => x.Chat)
            .HasForeignKey(x => x.ChatId)
            .OnDelete(DeleteBehavior.Cascade);
    }
}
